"""Original focused exercises mapped to all 79 existing EDB2017 unit IDs.
This is baseline coverage, NOT a claim that every official learning outcome is complete.
No real student data is generated. Source answers use rational expressions, independent QA separately.
"""
from pathlib import Path
import json,copy
R=Path(__file__).resolve().parents[1]
base=json.loads((R/'originals/WordQuest_Program_and_Data_20260929/02_Maths_0.1.2/source/curriculum.json').read_text())
new={'skills':[],'templates':[],'cards':[],'coverage':[]}
I=lambda a,b:{'int':[a,b]}
P=lambda xs:{'pick':xs}
E=lambda s:{'expr':s}
D=lambda s,n=1:{'decimal':{'expr':s,'places':n}}
L=lambda key,vals:{'lookup':{'from':key,'values':vals}}
un={u['id']:u for u in base['units']}

def add(unit,name,en,kind,params,zh,eng,answer,concept,explain,tool='numberline',visual='',typ='number',constraints=None,labels=None,level=None,strategy=None,extra=None):
    sid=unit+'.R3' if unit in un else unit
    grade=un[unit]['grade'] if unit in un else min(6,level+1)
    strand=un[unit]['strand'] if unit in un else 'O'
    sk={'id':sid,'unit':unit if unit in un else 'OLY-R3','track':'normal' if unit in un else 'olympiad','strand':strand,'grade':grade,'name_zh':name,'name_en':en,'tool':tool,'prerequisites':[], 'official_focus':unit if unit in un else None,'source_page':None,'status':'baseline-preview','coverage':'原創基礎選段；不是本官方單元的全部學習重點。','strategy':strategy,'level':level or 1,'lesson':{'scene':name+'：先觀察資料或圖像，再決定方法。','concept':concept,'explore':'在教具改變一項數量，觀察其他量如何改變。回到題目，圈出已知和未知。','remedy':concept+' 先用較小數字試一次，再回到原題。','alternative':explain,'reflection':'答案的單位和大小是否合理？可以用相反運算、圖像或逐項列出驗證嗎？','minutes':8 if grade<3 else 10},'r3_review':'not yet independently teacher reviewed'}
    new['skills'].append(sk)
    for diff in (1,2,3):
        ps=copy.deepcopy(params(diff) if callable(params) else params)
        t={'id':sid+'-T'+str(diff),'skill':sid,'difficulty':diff,'type':typ,'params':ps,'constraints':constraints or [],'stem_zh':zh,'stem_en':eng,'speech_yue':zh.replace('多少','幾多').replace('共有','總共有').replace('應該','應該'), 'answer':{'expr':answer},'distractors':[],'hints':[concept,'先寫下題目給出的數量，單位要一致。',explain,'最後按同一方法計算，並檢查有沒有漏掉任何一項。'],'explanation':explain+' 答案是 {r3Answer}。','visual':'r3:'+visual if visual else '', 'verification':{'kind':kind},'difficulty_note':{'basis':'按數字範圍／運算步驟設計，尚未用學生數據校準','level':diff}}
        # Store explicit result only for explanation, not the independent answer checker.
        ps['r3Answer']=E(answer)
        if labels:
            t['choiceLabels']=labels;t['choiceCount']=len(labels);t['type']='choice';ps['r3AnswerLabel']=L('idx',[labels[str(v)]['zh'] for v in [x for x in ps['ans']['lookup']['values']]]) if 'ans' in ps and 'lookup' in ps['ans'] else P([''])
            t['explanation']=explain
        if extra:t.update(extra)
        if kind in ['decimalParts','fractionDecimal','percentToDecimal']:t['answer']['formats']=['decimal','integer']
        if kind=='mixedFraction':t['answer']['formats']=['fraction']
        new['templates'].append(t)
    if unit in un:new['coverage'].append({'unit':unit,'added_skill':sid,'topic':name,'scope':sk['coverage']})

# Number topics: each exercise uses a concrete independent mathematical operation.
add('1N1','倒數與相鄰的數','Count backwards','prev',lambda d:{'a':I(3,6*d)},'由 {a} 倒數一個數，是多少？','Count back one from {a}. What number comes next?','a-1','倒數一個就是少一個，在數線向左走一格。','由 {a} 向左走一格，即 {a} − 1。')
add('1N2','把剩下的數找出來','Find what remains','subtract',lambda d:{'b':I(1,3*d),'c':I(1,3*d),'a':E('b+c')},'有 {a} 粒珠，拿走 {b} 粒，還有多少粒？','There are {a} beads. Remove {b}. How many remain?','a-b','減法把一部分拿走。原有數量減去拿走的數量，就是餘下的。','{a} − {b}，也可用 {b} 加上答案檢查是否得到 {a}。',tool='tenframe')
add('1N3','幾個十與幾個一','Tens and ones','place',lambda d:{'a':I(1,3*d),'b':I(0,9)},'{a} 個十和 {b} 個一合起來是多少？','What number has {a} tens and {b} ones?','a*10+b','每十個一換成一個十。數位決定數字的值。','{a} 個十是 {a} × 10，再加 {b} 個一。',tool='place')
add('1N4','兩位數加法','Add within 100','add',lambda d:{'a':I(10,10+8*d),'b':I(1,9*d)},'{a} + {b} = ？','Calculate {a} + {b}.','a+b','個位對個位，十位對十位；十個一可換成一個十。','把 {b} 分拆，先把 {a} 湊整十，再加餘下部分。',tool='blocks')
add('2N1','百、十、一的數值','Hundreds, tens and ones','hundreds',lambda d:{'a':I(1,3*d),'b':I(0,9),'c':I(0,9)},'{a} 個百、{b} 個十和 {c} 個一是多少？','Write the number with {a} hundreds, {b} tens and {c} ones.','a*100+b*10+c','每一位的值是左邊相鄰數位的十分之一。','計算 {a} × 100 + {b} × 10 + {c}。',tool='place')
add('2N2','三位數減法','Subtract three-digit numbers','subtract',lambda d:{'b':I(100,130*d),'c':I(10,120*d),'a':E('b+c')},'{a} − {b} = ？','Calculate {a} − {b}.','a-b','減法可用加法驗算。需要退位時，拆開一個十或一個百，總值不變。','從 {a} 拿走 {b}；用答案加 {b} 檢查。',tool='blocks')
add('2N3','相同數量的多組','Equal groups','multiply',lambda d:{'a':I(2,3*d),'b':I(2,3*d)},'每盒有 {a} 粒珠，{b} 盒共有多少粒？','Each box holds {a} beads. How many beads are in {b} boxes?','a*b','相同數量相加，可用乘法表示。','把 {a} 加 {b} 次，即 {a} × {b}。',tool='array')
add('2N4','四位數的組成','Compose four-digit numbers','thousands',lambda d:{'a':I(1,3*d),'b':I(0,9),'c':I(0,9),'e':I(0,9)},'{a} 個千、{b} 個百、{c} 個十和 {e} 個一是多少？','Write the number with {a} thousands, {b} hundreds, {c} tens and {e} ones.','a*1000+b*100+c*10+e','沒有某一數位時用0佔位，不可把其他數字左移。','千、百、十、一分別乘1000、100、10、1後相加。',tool='place')
add('2N5','四位數減法驗算','Check four-digit subtraction','subtract',lambda d:{'b':I(1000,1100*d),'c':I(100,900*d),'a':E('b+c')},'{a} − {b} = ？','Calculate {a} − {b}.','a-b','數位對齊後逐位減。需要退位時改寫數的分拆，但總值不變。','算好後把差加 {b}；結果應是 {a}。',tool='place')
add('2N6','平均分配與每份','Share equally','division',lambda d:{'b':I(2,3*d),'c':I(2,3*d),'a':E('b*c')},'{a} 件物件平均分給 {b} 人，每人有多少件？','Share {a} objects equally among {b} people. How many does each person get?','a/b','除法找每份有多少。每人一樣多，分完後沒有剩餘。','找一個數乘 {b} 得 {a}。',tool='array')
add('3N1','五位數中的萬與千','Ten-thousands and thousands','tenThousands',lambda d:{'a':I(1,3*d),'b':I(0,9),'c':I(0,99)},'{a} 個萬、{b} 個千和 {c} 個一是多少？','Write the number with {a} ten-thousands, {b} thousands and {c} ones.','a*10000+b*1000+c','各數位沒有數量時仍需要0佔位。','先組成 {a} × 10000 + {b} × 1000，再加 {c}。',tool='place')
add('3N2','整數乘一位數','Multiply by one digit','multiply',lambda d:{'a':I(12,35*d),'b':I(2,3*d)},'{a} × {b} = ？','Calculate {a} × {b}.','a*b','把被乘數按數位分拆，每部分乘同一個數，再相加。','可先算整十的部分，再算個位部分，最後相加。',tool='array')
add('3N3','有餘數的平均分','Divide with a remainder','remainder',lambda d:{'b':I(3,3*d),'c':I(2,20*d),'r':I(0,2),'a':E('b*c+r')},'{a} ÷ {b} 的商和餘數是多少？','Find the quotient and remainder of {a} ÷ {b}.','c','先分出完整的一份，剩下的數一定小於除數。','驗算：除數 × 商 + 餘數 = 被除數。',tool='array',typ='remainder',extra={'answer':{'expr':'c','remainder':'r'}})
add('3N4','先乘後加','Order of operations','mixed',lambda d:{'a':I(2,3*d),'b':I(2,3*d),'c':I(1,10*d)},'{c} + {a} × {b} = ？','Calculate {c} + {a} × {b}.','c+a*b','沒有括號時，先乘除，後加減。','先算 {a} × {b}，再加 {c}。',tool='array')
add('3N5','同分母分數相加','Add like fractions','sameFraction',lambda d:{'b':P([5,7,9,11]),'a':I(1,2),'c':I(1,2)},'{a}/{b} + {c}/{b} = ？','Calculate {a}/{b} + {c}/{b}.','(a+c)/b','每份一樣大，合併所選的份數，分母不變。','把 {a} 份和 {c} 份合在一起，每份仍是 1/{b}。',tool='fraction',typ='fraction')
add('4N1','兩位數相乘','Multiply two two-digit numbers','multiply',lambda d:{'a':I(11,20*d),'b':I(11,15*d)},'{a} × {b} = ？','Calculate {a} × {b}.','a*b','利用分配性質，把一個乘數拆成十位和個位。','先算 {a} 乘 {b} 的十位值，再加 {a} 乘其個位。',tool='array')
add('4N2','除以兩位數','Divide by two digits','division',lambda d:{'b':I(11,15*d),'c':I(2,6*d),'a':E('b*c')},'{a} ÷ {b} = ？','Calculate {a} ÷ {b}.','a/b','用倍數估計商，再用乘法檢查是否正好分完。','列出 {b}、2 × {b}、3 × {b}，直到找到 {a}。',tool='numberline')
add('4N3','找指定的倍數','Find a multiple','multiple',lambda d:{'a':I(2,4*d),'b':I(2,5*d)},'{a} 的第 {b} 個正倍數是多少？','What is the {b}-th positive multiple of {a}?','a*b','正倍數是原數乘1、2、3等正整數所得的數。','第 {b} 個正倍數就是 {a} × {b}。')
add('4N4','共同響起的時間','Least common multiples','lcmConsecutive',lambda d:{'k':I(1,3*d),'x':I(2,3+d),'a':E('k*x'),'b':E('k*(x+1)')},'甲鐘每 {a} 分鐘響，乙鐘每 {b} 分鐘響。現在同時響，最少再過多少分鐘同時響？','Bell A rings every {a} minutes and bell B every {b} minutes. They ring together now. How many minutes until they next ring together?','k*x*(x+1)','分別列出兩數的正倍數，最小的共同數就是最小公倍數。','逐列 {a} 和 {b} 的倍數，找第一個共同時間。',tool='table')
add('4N5','括號先算','Calculate inside brackets first','brackets',lambda d:{'a':I(12,30*d),'b':I(2,9),'c':I(2,7)},'({a} + {b}) × {c} = ？','Calculate ({a} + {b}) × {c}.','(a+b)*c','括號表示先把裏面的數量合成一組。','先把 {a} 加 {b}，再把整組乘 {c}。',tool='array')
add('4N6','帶分數轉假分數','Convert mixed numbers','mixedFraction',lambda d:{'a':I(1,3*d),'b':P([3,5,7,9]),'c':I(1,2)},'把帶分數 {a} 又 {c}/{b} 寫成假分數。','Write {a} and {c}/{b} as an improper fraction.','a+c/b','每個整數有分母所表示的份數，再加零散的份數。','分子是 {a} × {b} + {c}，分母仍是 {b}。',tool='fraction',typ='fraction')
add('4N7','十分位與百分位','Tenths and hundredths','decimalParts',lambda d:{'a':I(1,3*d),'b':I(0,9)},'{a} 個十分之一和 {b} 個百分之一，合起來是多少？請用小數。','Write {a} tenths plus {b} hundredths as a decimal.','a/10+b/100','一個十分之一等於十個百分之一；小數點後第一位是十分位。','把 {a} 個十分之一改寫成 {a} × 10 個百分之一，再加 {b} 個。',tool='fraction')
add('4N8','小數加法對齊','Align decimal places','decimalAdd',lambda d:{'ia':I(11,30*d),'ib':I(1,30*d),'a':D('ia/10'),'b':D('ib/10')},'{a} + {b} = ？','Calculate {a} + {b}.','a+b','小數點對齊，十分位對十分位，個位對個位。','也可把兩數都改成十分之一的個數，相加後換回。',tool='place')
add('5N1','四捨五入至千位','Round to the nearest thousand','roundThousand',lambda d:{'a':I(1000,200000*d),'r':E('floor((a+500)/1000)*1000')},'把 {a} 四捨五入至千位。','Round {a} to the nearest thousand.','r','看百位：0至4捨去，5至9令千位進一；更小的數位改為0。','先找前後兩個整千數，再判斷哪個較近。',tool='place')
add('5N2','異分母分數相加','Add unlike fractions','unlikeAdd',lambda d:{'a':I(1,2),'b':P([3,4,5]),'c':I(1,2),'e':P([6,8,10])},'{a}/{b} + {c}/{e} = ？','Calculate {a}/{b} + {c}/{e}.','a/b+c/e','先通分，使每一份同樣大，才可以相加。','可先用 {b} × {e} 作共同分母，兩個分子也要乘相應倍數。',tool='fraction',typ='fraction')
add('5N3','分數乘法','Multiply fractions','fractionMultiply',lambda d:{'a':I(1,d+1),'b':P([5,7,9]),'c':I(1,d+1),'e':P([5,7,9])},'{a}/{b} × {c}/{e} = ？','Calculate {a}/{b} × {c}/{e}.','a*c/(b*e)','一部分的另一部分可用乘法表示；分子相乘、分母相乘。','先算 {a} × {c} 及 {b} × {e}，需要時約分。',tool='fraction',typ='fraction')
add('5N4','小數乘整數','Multiply a decimal','decimalMultiply',lambda d:{'ia':I(11,30*d),'a':D('ia/10'),'b':I(2,3*d)},'{a} × {b} = ？','Calculate {a} × {b}.','a*b','先按整數乘法計，再按每份的單位換回十分之一。','{a} 是 {ia} 個十分之一。{ia} 乘 {b} 後再除以10。',tool='array')
add('5N5','分數除法','Divide fractions','fractionDivide',lambda d:{'a':I(1,d+1),'b':P([5,7,9]),'c':I(1,d+1),'e':P([5,7,9])},'{a}/{b} ÷ {c}/{e} = ？','Calculate {a}/{b} ÷ {c}/{e}.','a*e/(b*c)','除以一個非零分數，等於乘它的倒數。','保留第一個分數，乘 {e}/{c}；分子分母同乘後約分。',tool='fraction',typ='fraction')
add('6N1','小數除法','Divide decimal numbers','decimalDivide',lambda d:{'ib':I(2,3*d),'q':I(2,4*d),'b':D('ib/10'),'a':D('ib*q/10')},'{a} ÷ {b} = ？','Calculate {a} ÷ {b}.','a/b','被除數與除數同乘10，商不變；把除數化成整數。','兩數同乘10後做整數除法，再乘回除數驗算。',tool='place')
add('6N2','分數化小數','Fractions as decimals','fractionDecimal',lambda d:{'a':I(1,3*d),'b':P([10,20,25])},'把 {a}/{b} 化成小數。','Write {a}/{b} as a decimal.','a/b','分數表示分子除以分母，也可擴成分母100的分數。','把分母化成100時，分子也乘相同倍數。',tool='fraction')
add('6N3','百分數的意義','Read percentages','percentToDecimal',lambda d:{'a':I(1,30*d)},'{a}% 化成小數是多少？','Write {a}% as a decimal.','a/100','百分數表示每100份中有多少份；100%等於整個。','把 {a} 除以100，不是除以10。',tool='fraction')
add('6N4','折扣後的價錢','Calculate a discounted price','discount',lambda d:{'a':I(2,10*d),'price':E('a*10'),'p':P([10,20,25,30,50])},'原價 {price} 元，減價 {p}%，售價多少元？','An item costs {price} dollars before a {p}% discount. What is the sale price in dollars?','price*(100-p)/100','減價百分率不是售價百分率；售價是原價的100%減去減幅。','先算減去多少元，然後由 {price} 元扣除。',tool='money')
# Measurement. Low-primary examples intentionally avoid decimal unit conversions.
add('1M1','用同樣大小的單位量度','Measure with equal units','lengthUnits',lambda d:{'a':I(2,3*d),'b':I(1,d)},'短帶長 {a} 個積木單位，長帶比它長 {b} 個同樣單位。長帶多長？','A short ribbon is {a} equal blocks long. Another ribbon is {b} blocks longer. How many blocks long is it?','a+b','單位要同樣長，首尾相接，不留空隙、不重疊。','在 {a} 個相同單位後面，再接 {b} 個。',tool='ruler',visual='length')
add('1M2','數一數硬幣總值','Count coin values','coinSum',lambda d:{'a':I(1,3),'b':I(1,d)},'{a} 個1元硬幣和 {b} 個2元硬幣，共多少元？','What is the total value of {a} one-dollar coins and {b} two-dollar coins?','a+2*b','硬幣的枚數不等於總值；先按面值分組。','1元共 {a} 元，2元共 2 × {b} 元，再相加。',tool='money')
add('1M3','由尺的刻度讀長度','Read a ruler in centimetres','rulerLength',lambda d:{'start':I(0,d),'len':I(2,4*d),'end':E('start+len')},'紙條在尺上由 {start} 厘米至 {end} 厘米，長多少厘米？','A strip extends from {start} cm to {end} cm on a ruler. How long is it?','end-start','長度是終點與起點相差多少，不能只看終點數字。','由 {start} 數至 {end}，或用終點減起點。',tool='ruler',visual='ruler')
add('1M4','鐘面上的整點','Read whole hours','clockHour',lambda d:{'hour':I(1,4*d),'minute':P([0])},'鐘面的分針指向12。現在是幾點？只填小時。','The minute hand points to 12. What hour does the clock show?','hour','長針是分針，短針是時針。整點時分針指向12。','看短針指向哪個數字。',tool='clock',visual='clock')
add('2M1','米與厘米化聚','Convert metres to centimetres','metresCm',lambda d:{'a':I(1,3*d),'b':I(1,30*d)},'{a} 米 {b} 厘米等於多少厘米？','How many centimetres are in {a} metres and {b} centimetres?','a*100+b','1米等於100厘米，把單位統一後再加。','{a} 米先乘100，再加 {b} 厘米。',tool='ruler')
add('2M2','鐘面的分鐘','Read minutes on a clock','clockMinute',lambda d:{'hour':I(1,12),'idx':I(0,11),'minute':E('idx*5')},'鐘面顯示 {hour} 點多少分？只填分鐘。','The clock shows hour {hour}. How many minutes past the hour is it?','minute','分針每走一個大格是5分鐘，走一圈是60分鐘。','由12開始，以5、10、15順數至分針指向的刻度。',tool='clock',visual='clock')
add('2M3','付錢後找贖','Find change','change',lambda d:{'paid':P([20,50,100]),'cost':I(1,10*d)},'付款 {paid} 元，貨品售 {cost} 元，應找回多少元？','You pay {paid} dollars for an item costing {cost} dollars. How much change should you receive?','paid-cost','找贖等於付款減貨價，付款不能少於貨價。','用 {paid} 減 {cost}；貨價加找贖應等於付款。',tool='money',constraints=['paid>cost'])
add('3M1','厘米和毫米','Convert centimetres and millimetres','cmMm',lambda d:{'a':I(1,6*d),'b':I(1,9)},'{a} 厘米 {b} 毫米是多少毫米？','How many millimetres are in {a} centimetres and {b} millimetres?','a*10+b','1厘米有10毫米；先把厘米換成毫米。','{a} × 10 + {b}。',tool='ruler')
add('3M2','時間間隔','Elapsed time','elapsed',lambda d:{'start':I(1,15*d),'duration':I(2,4*d),'end':E('start+duration')},'同一小時內，活動由第 {start} 分鐘至第 {end} 分鐘，經過多少分鐘？','Within the same hour, an activity starts at minute {start} and ends at minute {end}. How many minutes pass?','end-start','經過時間由開始到結束計算；起點不是第一個已過的分鐘。','終點 {end} 減起點 {start}。',tool='clock',constraints=['end<60'])
