add('3M5','公斤與克','Convert kilograms and grams','kgG',lambda d:{'a':I(1,3*d),'b':I(20,250*d)},'{a} 公斤 {b} 克，共多少克？','How many grams are in {a} kilograms and {b} grams?','a*1000+b','1公斤等於1000克，不能把公斤直接與克相加。','把 {a} 公斤換成克，再加 {b} 克。',tool='ruler')
add('4M1','長方形周界','Rectangle perimeter','perimeter',lambda d:{'a':I(3,6*d),'b':I(2,4*d)},'長方形長 {a} 厘米，闊 {b} 厘米。周界多少厘米？','A rectangle is {a} cm long and {b} cm wide. Find its perimeter in cm.','2*(a+b)','周界是沿外邊走一圈的長度，四條邊都要計算。','兩條長和兩條闊：2 × ({a} + {b})。',tool='ruler',visual='rectangle')
add('4M2','方格與面積','Area of a rectangle','areaRectangle',lambda d:{'a':I(3,5*d),'b':I(2,3*d)},'長方形長 {a} 厘米，闊 {b} 厘米。面積多少平方厘米？','A rectangle is {a} cm long and {b} cm wide. Find its area in square cm.','a*b','面積是能鋪滿圖形的單位正方形數，不是外邊的長度。','每行 {a} 格，共 {b} 行，所以 {a} × {b}。',tool='array',visual='rectangle')
