# Conceptual geometry / statistics: numeric codes are hidden behind bilingual labels.
def concept(unit,name,en,kind,rows,labels,zh,eng,explain,tool='ruler',visual='shape'):
    # All rows present in every tier; rotation or evidence detail varies, not arbitrary answer-code arithmetic.
    def params(d):return {'idx':I(0,len(rows)-1),'shape':L('idx',[r[0] for r in rows]),'detail':L('idx',[{'zh':r[1],'en':r[2]} for r in rows]),'ans':L('idx',[r[3] for r in rows]),'rotation':P([0,15*d,30*d])}
    lab={str(i+1):{'zh':a,'en':b} for i,(a,b) in enumerate(labels)}
    add(unit,name,en,kind,params,zh,eng,'ans',explain,explain,tool=tool,visual=visual,typ='choice',labels=lab)
concept('1S1','辨認立體外形','Recognise solid shapes','solidClass', [('cube','六個平面都是正方形','All six flat faces are squares',1),('sphere','沒有平面，像球','No flat faces; shaped like a ball',2),('cylinder','兩個圓形平面，旁邊是曲面','Two flat circular faces and a curved surface',3),('cone','一個圓形平面，上方尖頂','One flat circular face and a pointed top',4)], [('方塊形','Cube'),('球形','Sphere'),('圓柱形','Cylinder'),('圓錐形','Cone')], '物件的特徵：{detail}。它是哪種外形？','An object has these features: {detail}. What shape is it?','觀察平面、曲面及整體外形，不用物件用途猜答案。',tool='solid',visual='solidType')
concept('1S2','按邊數認圖形','Classify flat shapes','polygonClass', [('triangle','3條直邊','3 straight sides',1),('square','4條直邊','4 straight sides',2),('pentagon','5條直邊','5 straight sides',3),('hexagon','6條直邊','6 straight sides',4)], [('三角形','Triangle'),('四邊形','Quadrilateral'),('五邊形','Pentagon'),('六邊形','Hexagon')], '一個封閉圖形有 {detail}，是甚麼圖形？','A closed shape has {detail}. What is it?','圖形可按直邊數分類；轉動或改變大小不會改變邊數。')
concept('1S3','看清左右前後','Relative positions','positionClass', [('left','小球在方盒左邊','The ball is to the left of the box',1),('right','小球在方盒右邊','The ball is to the right of the box',2),('above','小球在方盒上方','The ball is above the box',3),('below','小球在方盒下方','The ball is below the box',4)], [('左邊','Left'),('右邊','Right'),('上方','Above'),('下方','Below')], '以看圖者方向判斷，小球在方盒哪個位置？','From the viewer\'s position, where is the ball relative to the box?','先確定以看圖者的方向作參考，再說出兩件物件的相對位置。',visual='position')
concept('2S1','立體的平面形狀','Faces of solids','solidFace', [('cube','正方體的每一個面','Each face of a cube',1),('cylinder','圓柱的上下兩個平面','The two flat ends of a cylinder',2),('triangularPrism','三角柱兩個全等的底面','The two congruent bases of a triangular prism',3),('cuboid','長、闊、高各不相同的長方體的每一個面','Each face of a cuboid whose length, width and height are all different',4)], [('正方形','Square'),('圓形','Circle'),('三角形','Triangle'),('長方形','Rectangle')], '{detail}是甚麼形狀？','What shape is {detail}?','只計平面的形狀；曲面不叫圓形面。',tool='solid',visual='solidType')
concept('2S2','分辨銳角、直角和鈍角','Classify angles','angleClass', [('acute','比直角小','Smaller than a right angle',1),('rightangle','與直角一樣大','Equal to a right angle',2),('obtuse','比直角大，但未到平角','Larger than a right angle but smaller than a straight angle',3),('acute2','兩邊張開得比直角窄','A narrower opening than a right angle',1)], [('銳角','Acute angle'),('直角','Right angle'),('鈍角','Obtuse angle')], '圖中的角{detail}，屬於哪一種角？','The angle is {detail}. What type is it?','角的大小由兩邊張開程度決定，與邊畫得長或短無關。',tool='angle',visual='angleClass')
concept('2S3','東南西北的相反方向','Opposite compass directions','oppositeDirection', [('north','北','north',1),('south','南','south',2),('east','東','east',3),('west','西','west',4)], [('南','South'),('北','North'),('西','West'),('東','East')], '面向{detail}，轉身180°後面向哪一方？','You face {detail}. After a half turn, which direction do you face?','北與南相反，東與西相反。圖的上方標北時，右方是東。',visual='compass')
concept('2S4','正方形和長方形','Squares and rectangles','rectangleClass', [('square','四個角都是直角，四條邊相等','Four right angles and four equal sides',1),('rectangle','四個角都是直角，但鄰邊不相等','Four right angles and unequal adjacent sides',2),('square','每邊3厘米，四個角都是直角','Each side is 3 cm and all angles are right angles',1),('rectangle','長5厘米、闊2厘米，四個角都是直角','Length 5 cm, width 2 cm, all angles are right angles',2)], [('正方形','Square'),('長方形（非正方形）','Rectangle, not square')], '選最具體的名稱：{detail}。','Choose the most specific name: {detail}.','正方形的四條邊相等；正方形也屬於長方形，本題選較具體的名稱。')
concept('3S1','平行與四邊形','Parallel sides in quadrilaterals','parallelClass', [('parallelogram','兩組對邊分別平行，沒有直角','Two pairs of parallel opposite sides and no right angles',1),('trapezium','只有一組對邊平行','Exactly one pair of parallel opposite sides',2),('square','四個直角，四邊相等','Four right angles and four equal sides',3),('rectangle','四個直角，鄰邊不相等','Four right angles and unequal adjacent sides',4)], [('平行四邊形（非長方形）','Parallelogram, not rectangle'),('梯形','Trapezium'),('正方形','Square'),('長方形（非正方形）','Rectangle, not square')], '選最具體的名稱：{detail}。','Choose the most specific name: {detail}.','平行線延長後不相交；分類時須同時查看角和邊。',visual='shape')
