# Algebra, exact inverse operations.
add('5A1','把字母代入數值','Substitute into an expression','substitution',lambda d:{'a':I(2,5*d),'b':I(2,3*d),'c':I(1,5*d)},'當 x = {a}，{b}x + {c} 等於多少？','If x = {a}, find {b}x + {c}.','a*b+c','相鄰的數和字母表示相乘；把同一個字母用同一個數代入。','先算 {b} × {a}，再加 {c}。',tool='array')
add('5A2','一步方程','Solve one-step equations','oneEquation',lambda d:{'x':I(2,8*d),'a':I(2,6*d),'b':E('x+a')},'x + {a} = {b}，x 等於多少？','Solve x + {a} = {b}.','b-a','等式兩邊做相同運算，仍然相等。','兩邊同減 {a}，然後代回原式驗算。',tool='numberline')
add('6A1','兩步方程','Solve two-step equations','twoEquation',lambda d:{'x':I(2,6*d),'a':I(2,3*d),'b':I(1,10*d),'c':E('a*x+b')},'{a}x + {b} = {c}，x 等於多少？','Solve {a}x + {b} = {c}.','(c-b)/a','先消去加減部分，再消去乘除部分；每次兩邊做同一操作。','兩邊同減 {b}，再同除以 {a}。',tool='numberline')
# Three further olympiad levels, five distinct domains/strategies per level.
cards=[('inverse','倒推','從結果出發，用相反運算一步一步返回起點。','加3後乘2得到14：先14÷2，再減3。'),('parity','奇偶分析','留意奇數、偶數在加減或配對後的性質。','兩個奇數相加為偶數，可用小例子觀察。'),('assume','先作假設','先假設全部相同，再利用差額找出另一類的數量。','把全部車當成兩輪車，再按每輛多出的輪數調整。'),('pigeonhole','抽屜原理','把物件按類別分組，先考慮最分散的情況。','三種顏色，最壞先各拿一個，第4個必與某色相同。'),('systematic','有序計數','固定一部分，逐個改變另一部分，避免漏數和重複。','衣服每一件逐一配每一條褲，總數是兩數相乘。'),('invariant','找不變的量','步驟改變外觀時，找一直不變的量作檢查。','搬移物件不增加或減少時，總數不變。'),('pair','首尾配對','把兩端配成相同總和，減少重複加法。','1加10、2加9都等於11。')]
new['cards']=[{'id':k,'name':n,'description':d,'example':e} for k,n,d,e in cards]
for lev in [2,3,4]:
    common=lambda d,lev=lev: {'a':I(2,3*d+lev),'b':I(1,4*d+lev),'x':I(2,5*d+lev),'end':E('(x+a)*b')}
    add(f'O-R3-L{lev}-inverse','倒推：找原來的數',f'Work backwards level {lev}','inverse',common,'一個數先加 {a}，再乘 {b}，得 {end}。原數是多少？','A number is increased by {a}, then multiplied by {b}, giving {end}. What was the original number?','end/b-a','最後做乘法，倒推時先除；再把加法倒轉成減法。','先算 {end} ÷ {b}，再減 {a}。',level=lev,strategy='inverse')
    add(f'O-R3-L{lev}-count','有序計數：配搭',f'Systematic counting level {lev}','combinations',lambda d,lev=lev:{'a':I(2,d+lev),'b':I(2,d+lev),'c':I(1,lev-1)},'有 {a} 種上衣、{b} 種褲和 {c} 種帽。各選一款，共多少種配搭？','Choose one shirt, one pair of trousers and one hat from {a}, {b} and {c} choices respectively. How many outfits are possible?','a*b*c','先固定上衣，逐一配褲和帽，再換下一款上衣。','每種上衣有 {b} × {c} 種配搭，最後乘 {a}。',tool='table',level=lev,strategy='systematic')
    add(f'O-R3-L{lev}-geometry','方格中的長方形',f'Count rectangles level {lev}','gridRectangles',lambda d,lev=lev:{'a':I(1,min(5,d+lev-1)),'b':I(1,min(5,d+lev-1))},'圖中有 {a} 行、{b} 列單位方格，沿格線共可畫多少個長方形？包括正方形。','A grid has {a} rows and {b} columns of unit squares. How many rectangles can be drawn along grid lines, including squares?','a*(a+1)*b*(b+1)/4','一個長方形由兩條水平線和兩條垂直線確定；也可按長和闊逐類數。','水平線有 {a}+1 條，任選兩條；垂直線有 {b}+1 條，也任選兩條。',tool='array',visual='grid',level=lev,strategy='systematic')
    add(f'O-R3-L{lev}-logic','至少保證同色',f'Guarantee matching colours level {lev}','pigeonhole',lambda d,lev=lev:{'a':I(2,d+lev),'k':I(2,lev+1)},'袋中有 {a} 種顏色的球，每色數量充足。不看顏色拿球，最少拿多少個才能保證有 {k} 個同色？','A bag has {a} colours of balls, with plenty of each colour. How many draws without looking guarantee at least {k} balls of one colour?','a*(k-1)+1','考慮最不容易湊齊的情況：每種顏色先各拿少一個。','先算 {a} × ({k} − 1)，再多拿1個。',tool='tenframe',level=lev,strategy='pigeonhole')
    add(f'O-R3-L{lev}-applied','車輪問題：先假設',f'Assumption problems level {lev}','wheels',lambda d,lev=lev:{'cars':I(1,d+lev),'bikes':I(2,2*d+lev),'total':E('cars+bikes'),'wheels':E('cars*4+bikes*2')},'有兩輪單車和四輪車共 {total} 輛，共 {wheels} 個輪。四輪車有多少輛？','There are {total} vehicles: two-wheel bicycles and four-wheel cars. They have {wheels} wheels in total. How many cars are there?','(wheels-2*total)/2','先假設全部是兩輪車，每換一輛四輪車便多2個輪。','先用 {wheels} 減 2 × {total}，再除以2。',tool='table',level=lev,strategy='assume')
# Verify coverage and structural counts now; actual independent answers checked by a separate program.
assert len(new['coverage'])==79,(len(new['coverage']), sorted(set(un)-{x['unit'] for x in new['coverage']}))
assert len({s['id'] for s in new['skills']})==len(new['skills'])
new['revision']='R3-baseline-1';new['source']='EDB2017 pmc2017_tc.pdf, unit index; generated exercises are original, not official questions.'
(R/'r3_src/curriculum_extension.json').write_text(json.dumps(new,ensure_ascii=False,indent=2))
js='/* Original R3 baseline exercises. Not complete official-outcome or teacher certification. */\n(function(){const ext='+json.dumps(new,ensure_ascii=False,separators=(',',':'))+';const d=globalThis.WQMathData;d.skills.push(...ext.skills);d.templates.push(...ext.templates);d.cards.push(...ext.cards);for(const row of ext.coverage){const u=d.units.find(u=>u.id===row.unit);u.skills.push(row.added_skill);u.status="baseline-partial";}d.r3Coverage=ext.coverage;d.r3Revision=ext.revision;globalThis.WQR3Curriculum=ext;})();'
(R/'r3_src/curriculum_extension.js').write_text(js)
print('new',len(new['skills']),'skills',len(new['templates']),'templates; mapped units',len(new['coverage']))
